        src_path = convert_stacktrace_frame_path_to_source_path(frame=EventFrame.from_dict(ctx), platform=ctx['platform'], sdk_name=ctx['sdk_name'], code_mapping=config)
        if not src_path:
            result['error'] = 'stack_root_mismatch'
