        outcome = get_link(config, src_path, ctx['commit_id'], ctx['group_id'], ctx['abs_path'])
        result['iteration_count'] += 1
        result['current_config'] = {'config': config, 'outcome': outcome, 'repository': config.repository}
        if outcome.get('sourceUrl') and outcome['sourceUrl']:
            result['source_url'] = outcome['sourceUrl']
            return result
    return result

def makeService(self, options):
    serverType = config.ProcessType
    serviceMethod = getattr(self, 'makeService_%s' % (serverType,), None)
    if not serviceMethod:
        raise UsageError('Unknown server type %s. Please choose: Master, Slave or Combined' % (serverType,))
    else:
        service = serviceMethod(options)
        def location(frame):
            if frame is None:
                return 'Unknown'
            else:
                return '%s: %s' % (frame.f_code.co_name, frame.f_lineno)
        def sighup_handler(num, frame):
            log.error('SIGHUP recieved at %s' % (location(frame),))
            config.reload()
        signal.signal(signal.SIGHUP, sighup_handler)
        return service

