        policy = {'Action': ['s3:GetObject'], 'Resource': arn, 'Effect': 'Allow', 'Principal': '*'}
    bucket_policy = BucketPolicy('StaticBucketPolicy', Bucket=Ref(bucket), PolicyDocument={'Statement': [policy]})
    template.add_output(Output('StaticBucketName', Description='S3 bucket name', Value=Ref(bucket)))
    map(template.add_resource, [bucket, bucket_policy])

def _mirror_loads(model, nid_offset=0, eid_offset=0):
    for (unused_load_id, loads) in iteritems(model.loads):
        for load in loads:
            loads_new = []
            load_type = load.type
            if load_type == 'PLOAD4':
                g1 = None
                g34 = None
                if load.g1 is not None:
                    g1 = load.g1 + nid_offset
                if load.g34 is not None:
                    g34 = load.g34 + nid_offset
                eids = [eid + eid_offset for eid in load.eids]
                load2 = PLOAD4(load.sid, eids, load.pressures, g1, g34, cid=load.cid, nvector=load.nvector, surf_or_line=load.surf_or_line, line_load_dir=load.line_load_dir, comment='')
                loads_new.append(load)
            else:
                model.log.warning('skipping:\n%s' % load.rstrip())
        if loads_new:
            loads += loads_new

