def apply(cls, writer: IncrementalPdfFileWriter, style, dest_page,
          x, y, url, text_params=None):

    stamp = cls(writer, url, style, text_params)
    stamp_ref = writer.add_object(stamp)
    # randomise resource name to avoid conflicts
    resource_name = '/QRStamp' + os.urandom(16).hex()
    stamp_paint = 'q 1 0 0 1 %f %f cm %s Do Q' % (
        rd(x), rd(y), resource_name
    )
    stamp_wrapper_stream = generic.StreamObject.initializeFromDictionary({
        '__streamdata__': stamp_paint.encode('ascii'),
        pdf_name('/Length'): len(stamp_paint)
    })
    resources = generic.DictionaryObject({
        pdf_name('/XObject'): generic.DictionaryObject({
            pdf_name(resource_name): stamp_ref
        })
    })
    writer.add_stream_to_page(
        dest_page, writer.add_object(stamp_wrapper_stream), resources
    )
    stamp.render_all()
    # TODO add link annotation!
    return stamp_ref

def __getattr__(self, key):
    if ((key == "value" and "value" not in self.data) or
        (key == "type" and "type" not in self.data)) and \
            hasattr(self, "save_as_artifact"):
        with tempfile.TemporaryDirectory() as tmpdir:
            try:
                download_artifact(self, path=tmpdir)
                fs = os.listdir(tmpdir)
                assert len(fs) == 1
                with open(os.path.join(tmpdir, fs[0]), "r") as f:
                    content = jsonpickle.loads(f.read())
                    self.value = content
                    # For backward compatibility
                    # TODO: delete me in the future
                    if isinstance(content, dict) and "value" in content:
                        if "type" in content:
                            self.type = content["type"]
                        if "type" in content and \
                                content["type"] != str(str):
                            self.value = jsonpickle.loads(content["value"])
                        else:
                            self.value = content["value"]
            except Exception as e:
                logger.warning("Failed to load parameter value from "
                               "artifact: %s" % e)
    if key == "value" and hasattr(self, "description") and \
            self.description is not None:
        desc = jsonpickle.loads(self.description)
        if desc["type"] != str(str):
            try:
                return jsonpickle.loads(super().__getattr__("value"))
            except Exception as e:
                logger.warning("Failed to unpickle parameter: %s" % e)
    return super().__getattr__(key)

