        knowledge_base.ReadSystemConfigurationArtifact(stream_number, system_configuration)

def _session(request):
    engine = request.registry['sqlalchemy.engine']
    session = Session(bind=engine)
    try:
        tm = request.tm
    except AttributeError:
        pass
    else:
        zope.sqlalchemy.register(session, transaction_manager=tm)
    @request.add_finished_callback
    def close_the_sqlalchemy_session(request):
        if session.dirty:
            request.sentry.captureMessage('closing a dirty session', stack=True, extra={'dirty': session.dirty})
        session.close()
    return session

