def _do_load(self, data, many=None, partial=None, postprocess=True):
    errors = {}
    many = self.many if many is None else bool(many)
    if partial is None:
        partial = self.partial
    try:
        processed_data = self._invoke_load_processors(PRE_LOAD, data, many, original_data=data)
    except ValidationError as err:
        errors = err.normalized_messages()
        result = None
    if not errors:
        try:
            result = self._unmarshal(processed_data, self.fields, many=many, partial=partial, dict_class=self.dict_class, index_errors=self.opts.index_errors)
        except ValidationError as error:
            result = error.data
        self._invoke_field_validators(data=result, many=many)
        errors = self._unmarshal.errors
        field_errors = bool(errors)
        try:
            self._invoke_validators(pass_many=True, data=result, original_data=data, many=many, field_errors=field_errors)
        except ValidationError as err:
            errors.update(err.messages)
        try:
            self._invoke_validators(pass_many=False, data=result, original_data=data, many=many, field_errors=field_errors)
        except ValidationError as err:
            errors.update(err.messages)
    if not errors and postprocess:
        try:
            result = self._invoke_load_processors(POST_LOAD, result, many, original_data=data)
        except ValidationError as err:
            errors = err.normalized_messages()
    if errors:
        exc = ValidationError(errors, field_names=self._unmarshal.error_field_names, fields=self._unmarshal.error_fields, data=data, **self._unmarshal.error_kwargs)
        self.handle_error(exc, data)
        if self.strict:
            raise exc
    return (result, errors)

def _resolve_descriptors(self, name, types):
    name_scope = name.get_definition().get_parent_scope()
    if not isinstance(name_scope, (er.Instance, pr.Class)):
        return types
    result = []
    for r in types:
        try:
            desc_return = r.get_descriptor_returns
        except AttributeError:
            result.append(r)
        else:
            result += desc_return(self.scope)
    return result

