def handle_create(self):
    security_groups = self._get_security_groups()
    userdata = self.properties[self.USER_DATA] or ''
    flavor = self.properties[self.INSTANCE_TYPE]
    availability_zone = self.properties[self.AVAILABILITY_ZONE]
    image_name = self.properties[self.IMAGE_ID]
    image_id = self.client_plugin('glance').get_image_id(image_name)
    flavor_id = self.client_plugin().get_flavor_id(flavor)
    scheduler_hints = {}
    if self.properties[self.NOVA_SCHEDULER_HINTS]:
        for tm in self.properties[self.NOVA_SCHEDULER_HINTS]:
            hint = tm[self.NOVA_SCHEDULER_HINT_KEY]
            hint_value = tm[self.NOVA_SCHEDULER_HINT_VALUE]
            if hint in scheduler_hints:
                if isinstance(scheduler_hints[hint], six.string_types):
                    scheduler_hints[hint] = [scheduler_hints[hint]]
                scheduler_hints[hint].append(hint_value)
            else:
                scheduler_hints[hint] = hint_value
    else:
        scheduler_hints = None
    if cfg.CONF.stack_scheduler_hints:
        if scheduler_hints is None:
            scheduler_hints = {}
        scheduler_hints['heat_root_stack_id'] = self.stack.root_stack_id()
        scheduler_hints['heat_stack_id'] = self.stack.id
        scheduler_hints['heat_stack_name'] = self.stack.name
        scheduler_hints['heat_path_in_stack'] = self.stack.path_in_stack()
        scheduler_hints['heat_resource_name'] = self.name
    nics = self._build_nics(self.properties[self.NETWORK_INTERFACES], security_groups=security_groups, subnet_id=self.properties[self.SUBNET_ID])
    block_device_mapping = self._build_block_device_mapping(self.properties.get(self.BLOCK_DEVICE_MAPPINGS))
    server = None
    try:
        server = self.client().servers.create(name=self.physical_resource_name(), image=image_id, flavor=flavor_id, key_name=self.properties[self.KEY_NAME], security_groups=security_groups, userdata=self.client_plugin().build_userdata(self.metadata_get(), userdata, 'ec2-user'), meta=self._get_nova_metadata(self.properties), scheduler_hints=scheduler_hints, nics=nics, availability_zone=availability_zone, block_device_mapping=block_device_mapping)
    finally:
        if server is not None:
            self.resource_id_set(server.id)
    creator = nova_cp.ServerCreateProgress(server.id)
    attachers = []
    for (vol_id, device) in self.volumes():
        attachers.append(cinder_cp.VolumeAttachProgress(self.resource_id, vol_id, device))
    return (creator, tuple(attachers))

