def _preprocess(features, wires, pad_with, normalize):
    shape = qml.math.shape(features)
    if len(shape) != 1:
        raise ValueError(f'Features must be a one-dimensional tensor; got shape {shape}.')
    n_features = shape[0]
    if pad_with is None and n_features != 2 ** len(wires):
        raise ValueError(f"Features must be of length {2 ** len(wires)}; got length {n_features}. Use the 'pad' argument for automated padding.")
    if pad_with is not None and n_features > 2 ** len(wires):
        raise ValueError(f'Features must be of length {2 ** len(wires)} or smaller to be padded; got length {n_features}.')
    if pad_with is not None and n_features < 2 ** len(wires):
        padding = [pad_with] * (2 ** len(wires) - n_features)
        features = qml.math.concatenate([features, padding], axis=0)
    norm = qml.math.sum(qml.math.abs(features) ** 2)
    if not qml.math.allclose(norm, 1.0, atol=TOLERANCE):
        if normalize or pad_with:
            features = features / np.sqrt(norm)
        else:
            raise ValueError(f"Features must be a vector of length 1.0; got length {norm}.Use 'normalize=True' to automatically normalize.")
    return features

