def _apply_to_impl(self, instance, **kwds):
    config = self.CONFIG(kwds.pop('options', {}))
    if 'default_bigM' in kwds:
        logger.warn("DEPRECATED: the 'default_bigM=' argument has been replaced by 'bigM='")
        config.bigM = kwds.pop('default_bigM')
    config.set_value(kwds)
    bigM = config.bigM
    self.assume_fixed_vars_permanent = config.assume_fixed_vars_permanent
    targets = config.targets
    if targets is None:
        targets = (instance,)
    knownBlocks = {}
    for t in targets:
        if not is_child_of(parent=instance, child=t, knownBlocks=knownBlocks):
            raise GDP_Error("Target '%s' is not a component on instance '%s'!" % (t.name, instance.name))
        elif t.ctype is Disjunction:
            if t.is_indexed():
                self._transform_disjunction(t, bigM)
            else:
                self._transform_disjunctionData(t, bigM, t.index())
        elif t.ctype in (Block, Disjunct):
            if t.is_indexed():
                self._transform_block(t, bigM)
            else:
                self._transform_blockData(t, bigM)
        else:
            raise GDP_Error("Target '%s' was not a Block, Disjunct, or Disjunction. It was of type %s and can't be transformed." % (t.name, type(t)))
    if bigM is not None:
        unused_args = ComponentSet(bigM.keys()) - ComponentSet(self.used_args.keys())
        if len(unused_args) > 0:
            warning_msg = 'Unused arguments in the bigM map! These arguments were not used by the transformation:\n'
            for component in unused_args:
                if hasattr(component, 'name'):
                    warning_msg += '\t%s\n' % component.name
                else:
                    warning_msg += '\t%s\n' % component
            logger.warn(warning_msg)

