def normalize_exception(self, space):
    w_type = self.w_type
    w_value = self.w_value
    if space.full_exceptions:
        while space.is_true(space.isinstance(w_type, space.w_tuple)):
            w_type = space.getitem(w_type, space.wrap(0))
    if space.is_true(space.abstract_isclass(w_type)):
        if space.is_w(w_value, space.w_None):
            w_value = space.call_function(w_type)
            w_type = space.abstract_getclass(w_value)
        else:
            w_valuetype = space.abstract_getclass(w_value)
            if space.is_true(space.abstract_issubclass(w_valuetype, w_type)):
                w_type = w_valuetype
            else:
                if space.full_exceptions and space.is_true(space.isinstance(w_value, space.w_tuple)):
                    w_value = space.call(w_type, w_value)
                else:
                    w_value = space.call_function(w_type, w_value)
                w_type = space.abstract_getclass(w_value)
    elif space.full_exceptions and space.is_w(space.type(w_type), space.w_str):
        space.warn('raising a string exception is deprecated', space.w_DeprecationWarning)
    else:
        if not space.is_w(w_value, space.w_None):
            raise OperationError(space.w_TypeError, space.wrap('instance exception may not have a separate value'))
        w_value = w_type
        w_type = space.abstract_getclass(w_value)
        if space.full_exceptions:
            if space.findattr(w_value, space.wrap('__dict__')) is None and space.findattr(w_value, space.wrap('__slots__')) is None:
                msg = "raising built-in objects can be ambiguous, use 'raise type, value' instead"
                raise OperationError(space.w_TypeError, space.wrap(msg))
    self.w_type = w_type
    self.w_value = w_value

def transform(self, X, y=None):
    X = check_array(X)
    if self.mean_ is not None:
        X = X - self.mean_
    X = fast_dot(X, self.components_.T)
    return X

