    self.send_command(Pay2023.CMD_PRINT_CHEQUE, Cidade='"%s"' % city[:27], Data=date.strftime('#%d/%m/%Y#'), Favorecido='"%s"' % thirdparty[:45], Valor=self.format_value(value), **data)

def data_generation(self, freq: str='H', drop: bool=True, frac: float=0.95) -> TimeSeriesData:
    time = pd.date_range('2018-01-01', '2020-01-01', freq=freq)
    n = len(time)
    x = np.arange(n)
    values = np.abs(np.sin(30 * x) + 5 * x + 10 * x ** 2) + np.random.randn(n)
    df = pd.DataFrame(values, columns=['value'])
    df['time'] = time
    if drop:
        df = cast(pd.DataFrame, df.sample(frac=frac, replace=False))
    return TimeSeriesData(df)

def post(self, request: Request) -> Response:
    categories = ['awarding_agency', 'awarding_subagency', 'funding_agency', 'funding_subagency', 'recipient', 'recipient_duns', 'recipient_parent_duns', 'cfda', 'psc', 'naics', 'county', 'district', 'country', 'state_territory', 'federal_account']
    models = [{'name': 'category', 'key': 'category', 'type': 'enum', 'enum_values': categories, 'optional': False}, {'name': 'subawards', 'key': 'subawards', 'type': 'boolean', 'default': False, 'optional': True}]
    models.extend(copy.deepcopy(AWARD_FILTER))
    models.extend(copy.deepcopy(PAGINATION))
    original_filters = request.data.get('filters')
    validated_payload = TinyShield(models).block(request.data)
    business_logic_lookup = {'awarding_agency': AwardingAgencyViewSet().perform_search, 'awarding_subagency': AwardingSubagencyViewSet().perform_search, 'cfda': CfdaViewSet().perform_search, 'country': CountryViewSet().perform_search, 'county': CountyViewSet().perform_search, 'district': DistrictViewSet().perform_search, 'federal_account': FederalAccountViewSet().perform_search, 'funding_agency': FundingAgencyViewSet().perform_search, 'funding_subagency': FundingSubagencyViewSet().perform_search, 'naics': NAICSViewSet().perform_search, 'psc': PSCViewSet().perform_search, 'recipient': RecipientViewSet().perform_search, 'recipient_duns': RecipientDunsViewSet().perform_search, 'state_territory': StateTerritoryViewSet().perform_search}
    business_logic_func = business_logic_lookup.get(validated_payload['category'])
    if not business_logic_func:
        self.raise_not_implemented(validated_payload)
    raw_response = business_logic_func(validated_payload, original_filters)
    return Response(raw_response)

