def update_accounting_rules(self, data: list[dict[str, Any]], version: int) -> None:
    log.info(f'Applying update for accounting rules to v{version}')
    rules_db = DBAccountingRules(self.user_db)
    for rule_data in data:
        try:
            event_type = HistoryEventType.deserialize(rule_data['event_type'])
            event_subtype = HistoryEventSubType.deserialize(rule_data['event_subtype'])
            counterparty = rule_data['counterparty'] if rule_data['counterparty'] is not None else NO_ACCOUNTING_COUNTERPARTY
            rule = BaseEventSettings(taxable=rule_data['taxable'], count_entire_amount_spend=rule_data['count_entire_amount_spend'], count_cost_basis_pnl=rule_data['count_cost_basis_pnl'], accounting_treatment=TxAccountingTreatment.deserialize(rule_data['accounting_treatment']) if rule_data['accounting_treatment'] else None)
        except (KeyError, DeserializationError) as e:
            log.error(f'Failed to read key {e} while iterating new accounting rules')
            continue
        try:
            rules_db.add_accounting_rule(event_type=event_type, event_subtype=event_subtype, counterparty=counterparty, rule=rule, links={} if 'links' not in rule_data else rule_data['links'])
        except InputError as e:
            (rules, _) = rules_db.query_rules_and_serialize(filter_query=AccountingRulesFilterQuery.make(event_types=[event_type], event_subtypes=[event_subtype], counterparties=[counterparty]))
            if len(rules) == 1:
                self.msg_aggregator.add_message(message_type=WSMessageType.ACCOUNTING_RULE_CONFLICT, data={'local_rule': rules[0], 'remote_rule': rule_data})
            log.debug(f'Failed to add accounting rule {rule_data} due to {e}')
            continue

