def __getitem__(self, idx: int) -> Tuple[torch.Tensor, torch.Tensor]:
    chunk = self.data[idx:idx + self.block_size + 1]
    dix = [self.stoi[s] for s in chunk]
    x = torch.tensor(dix[:-1], dtype=torch.long)
    y = torch.tensor(dix[1:], dtype=torch.long)
    return (x, y)

def transform_points(dst_pose_src, points_src):
    if not torch.is_tensor(dst_pose_src) or not torch.is_tensor(points_src):
        raise TypeError('Input type is not a torch.Tensor')
    if not dst_pose_src.device == points_src.device:
        raise TypeError('Tensor must be in the same device')
    if not len(dst_pose_src.shape) == 3 or not len(points_src.shape) == 3:
        raise ValueError('Input size must be a three dimensional tensor')
    if not dst_pose_src.shape[0] == points_src.shape[0]:
        raise ValueError('Input batch size must be the same for both tensors')
    if not dst_pose_src.shape[2] == points_src.shape[2] + 1:
        raise ValueError('Input dimensions must differe by one unit')
    points_src_h = convert_points_to_homogeneous(points_src)
    points_dst_h = torch.matmul(dst_pose_src, points_src_h.transpose(1, 2))
    points_dst_h = points_dst_h.permute(0, 2, 1)
    points_dst = convert_points_from_homogeneous(points_dst_h)
    return points_dst

def unwrap_arguments(xml_response):
    xml_response = xml_response.encode('utf-8')
    try:
        tree = XML.fromstring(xml_response)
    except XML.ParseError:
        filtered = illegal_xml_re.sub('', xml_response.decode('utf-8')).encode('utf-8')
        tree = XML.fromstring(filtered)
    action_response = tree.find('{http://schemas.xmlsoap.org/soap/envelope/}Body')[0]
    return dict(((i.tag, i.text or '') for i in action_response))

def make_selection(cls, selected, children, max_count, mode):
    rand = random.Random()
    selected = set((tuple(k) for k in selected))
    valid_block_keys = set([(c.block_type, c.block_id) for c in children])
    invalid_block_keys = selected - valid_block_keys
    if invalid_block_keys:
        selected -= invalid_block_keys
    overlimit_block_keys = set()
    if len(selected) > max_count:
        num_to_remove = len(selected) - max_count
        overlimit_block_keys = set(rand.sample(selected, num_to_remove))
        selected -= overlimit_block_keys
    num_to_add = max_count - len(selected)
    added_block_keys = None
    if num_to_add > 0:
        pool = valid_block_keys - selected
        if mode == 'random':
            num_to_add = min(len(pool), num_to_add)
            added_block_keys = set(rand.sample(pool, num_to_add))
        else:
            raise NotImplementedError('Unsupported mode.')
        selected |= added_block_keys
    return {'selected': selected, 'invalid': invalid_block_keys, 'overlimit': overlimit_block_keys, 'added': added_block_keys}

