def add_class(self, cls):
    if self.has_class(cls):
        return
    ns = cls.get_namespace()
    tn = cls.get_type_name()
    if not ns in self.imports:
        self.imports[ns] = set()
    extends = getattr(cls, '__extends__', None)
    if not extends is None:
        self.add_class(extends)
        parent_ns = extends.get_namespace()
        if parent_ns != ns and (not parent_ns in self.imports[ns]) and self.is_valid_import(parent_ns):
            self.imports[ns].add(parent_ns)
            logger.debug('\timporting %r to %r because %r extends %r' % (parent_ns, ns, cls.get_type_name(), extends.get_type_name()))
    class_key = '{%s}%s' % (ns, tn)
    logger.debug('\tadding class %r for %r' % (repr(cls), class_key))
    assert class_key not in self.classes, "Somehow, you're trying to overwrite %r by %r for class key %r." % (self.classes[class_key], cls, class_key)
    self.classes[class_key] = cls
    if ns == self.get_tns():
        self.classes[tn] = cls
    if issubclass(cls, ComplexModelBase):
        for (k, v) in cls._type_info.items():
            if v is None:
                continue
            self.add_class(v)
            child_ns = v.get_namespace()
            if child_ns != ns and (not child_ns in self.imports[ns]) and self.is_valid_import(child_ns):
                self.imports[ns].add(child_ns)
                logger.debug('\timporting %r to %r for %s.%s(%r)' % (child_ns, ns, cls.get_type_name(), k, v))

def validate_role_yaml(role_data=None, role_path=None):
    if role_data and role_path or (not role_data and (not role_path)):
        raise ValueError('Either role_data OR role_path must be specified')
    if role_path:
        with open(role_path, 'r') as f:
            role_data = f.read()
    try:
        role = yaml.safe_load(role_data)[0]
    except yaml.YAMLError:
        raise RoleMetadataError('Unable to parse role yaml')
    schema = {'name': {'type': str}, 'CountDefault': {'type': int}, 'HostnameFormatDefault': {'type': str}, 'upgrade_batch_size': {'type': int}, 'ServicesDefault': {'type': list}, 'tags': {'type': list}, 'description': {'type': str}, 'networks': {'type': [list, dict]}, 'networks_skip_config': {'type': list}}
    if 'name' not in role:
        raise RoleMetadataError('Role name is missing from the role')
    for k in schema:
        if k in role:
            if k == 'networks':
                if not (isinstance(role[k], schema[k]['type'][0]) or isinstance(role[k], schema[k]['type'][1])):
                    msg = "Role '{}': {} is not of expected type {}".format(role['name'], k, schema[k]['type'])
                    raise RoleMetadataError(msg)
            elif not isinstance(role[k], schema[k]['type']):
                msg = "Role '{}': {} is not of expected type {}".format(role['name'], k, schema[k]['type'])
                raise RoleMetadataError(msg)
    return role

def __init__(self, **kw):
    for (k, v) in kw.items():
        if k not in ['name', 'description']:
            setattr(self, k, v)
    if not kw.has_key('version'):
        try:
            kw['version'] = self.version
        except AttributeError:
            raise AssertionError("Missing required parameter 'version'.")
    if not kw.has_key('description'):
        if self.__doc__ is not None:
            kw['description'] = self.__doc__
        else:
            raise AssertionError("Missing required parameter 'description'.")
    def argparser_factory(*args, **kwargs):
        kwargs.setdefault('conflict_handler', 'resolve')
        kwargs.setdefault('formatter_class', cli._ext.argparse.RawDescriptionHelpFormatter)
        return cli.app.CommandLineApp.argparser_factory(*args, **kwargs)
    self.argparser_factory = argparser_factory
    cli.app.CommandLineApp.__init__(self, name=os.path.splitext(os.path.basename(sys.argv[0]))[0], **kw)
    self.verbose_logging_threshold = 0

