            statsd_client.incr('callback.ses.{}'.format(notification_status))
            if notification.sent_at:
                statsd_client.timing_with_dates('callback.ses.elapsed-time'.format(client_name.lower()), datetime.utcnow(), notification.sent_at)
            create_outcome_notification_statistic_tasks(notification)
            return
        except KeyError:
            error = 'SES callback failed: messageId missing'
            return error
    except ValueError:
        error = '{} callback failed: invalid json'.format(client_name)
        return error

