def check_no_contextlib_nested(logical_line, filename):
    msg = 'N324: contextlib.nested is deprecated. With Python 2.7 and later the with-statement supports multiple nested objects. See https://docs.python.org/2/library/contextlib.html#contextlib.nested for more information.'
    if contextlib_nested.match(logical_line):
        yield (0, msg)

def deploy_axis_func(cls, axis, func, f_args, f_kwargs, num_splits, maintain_partitioning, *partitions, lengths=None, manual_partition=False):
    dataframe = pandas.concat(list(partitions), axis=axis, copy=False)
    result = func(dataframe, *f_args, **f_kwargs)
    if num_splits == 1:
        lengths = None
    elif manual_partition:
        lengths = list(lengths)
    elif num_splits != len(partitions) or not maintain_partitioning:
        lengths = None
    elif axis == 0:
        lengths = [len(part) for part in partitions]
        if sum(lengths) != len(result):
            lengths = None
    else:
        lengths = [len(part.columns) for part in partitions]
        if sum(lengths) != len(result.columns):
            lengths = None
    return split_result_of_axis_func_pandas(axis, num_splits, result, lengths)

