def __init__(self, ds, normal, fields, center='c', width=None, axes_unit=None, origin='center-window', fontsize=18, field_parameters=None, window_size=8.0, aspect=None, data_source=None, buff_size=(800, 800), *, north_vector=None):
    if north_vector is not None:
        mylog.warning("Ignoring 'north_vector' keyword as it is ill-defined for an AxisAlignedSlicePlot object.")
        del north_vector
    normal = self.sanitize_normal_vector(ds, normal)
    axis = fix_axis(normal, ds)
    (bounds, center, display_center) = get_window_parameters(axis, center, width, ds)
    if field_parameters is None:
        field_parameters = {}
    if isinstance(ds, YTSpatialPlotDataset):
        slc = ds.all_data()
        slc.axis = axis
        if slc.axis != ds.parameters['axis']:
            raise RuntimeError(f"Original slice axis is {ds.parameters['axis']}.")
    else:
        slc = ds.slice(axis, center[axis], field_parameters=field_parameters, center=center, data_source=data_source)
        slc.get_data(fields)
    validate_mesh_fields(slc, fields)
    PWViewerMPL.__init__(self, slc, bounds, origin=origin, fontsize=fontsize, fields=fields, window_size=window_size, aspect=aspect, buff_size=buff_size, geometry=ds.geometry)
    if axes_unit is None:
        axes_unit = get_axes_unit(width, ds)
    self.set_axes_unit(axes_unit)

