def test_update_with_api_exception(self):
    url = reverse('api:v1:course-detail', kwargs={'key': self.course.uuid})
    course_data = {
        'title': 'Course title',
        'entitlements': [
            {
                'price': 1000,
            },
        ],
    }

    # TODO: Remove draft=True and save lines below as part of DISCO-818
    self.course.draft = True
    self.course.save()

    with mock.patch(
        'course_discovery.apps.api.v1.views.courses.CourseViewSet.update_entitlement',
        side_effect=IntegrityError
    ):
        with LogCapture(course_logger.name) as log_capture:
            response = self.client.patch(url, course_data, format='json')
            self.assertEqual(response.status_code, 400)
            log_capture.check(
                (
                    course_logger.name,
                    'ERROR',
                    'An error occurred while setting Course or Course Run data.',
                )
            )

def parse_revdep_config(revdep_confdir):
	''' Parses all files under /etc/revdep-rebuild/ and returns
		tuple of: (masked_dirs, masked_files, search_dirs)'''

	search_dirs = set()
	masked_dirs = set()
	masked_files = set()

	#TODO: remove hard-coded path
	for _file in os.listdir(revdep_confdir):
		for line in open(os.path.join('/etc/revdep-rebuild', _file)):
			line = line.strip()
			#first check for comment, we do not want to regex all lines
			if not line.startswith('#'): 
				m = re.match('LD_LIBRARY_MASK=\\"([^"]+)\\"', line)
				if m is not None:
					s = m.group(1).split(' ')
					masked_files = masked_files.union(s)
					continue
				m = re.match('SEARCH_DIRS_MASK=\\"([^"]+)\\"', line)
				if m is not None:
					s = m.group(1).split(' ')
					for ss in s:
						masked_dirs = masked_dirs.union(glob.glob(ss))
					continue
				m = re.match('SEARCH_DIRS=\\"([^"]+)\\"', line)
				if m is not None:
					s = m.group(1).split()
					for ss in s:
						search_dirs = search_dirs.union(glob.glob(ss))
					continue

	return (masked_dirs, masked_files, search_dirs)

